/// Published: one room per machine the project's owner owns and links it to — with its tabs and that machine's name — is readable by anyone with the link. A link to somebody else's machine never becomes a room.\n  isPublic          Boolean            @default(false) @map(\"is_public\")\n  lastTerminalAt    DateTime?          @map(\"last_terminal_at\")\n  createdAt         DateTime           @default(now()) @map(\"created_at\")\n  owner             User?              @relation(\"ProjectOwner\", fields: [ownerId], references: [id], onDelete: SetNull)\n  /// Machines this project runs on, each with its own working directory.\n  machines          ProjectMachine[]\n  tabs              Tab[]\n  tasks             Task[]\n  note              Note?\n  setup             ProjectSetup?\n  tickets           Ticket[]\n  chatConversations ChatConversation[]\n  groupItems        ProjectGroupItem[]\n\n  @@index([ownerId])\n  @@map(\"projects\")\n}\n\n/// A project linked to a machine: where its terminals run and in which directory.\nmodel ProjectMachine {\n  id        String   @id\n  projectId String   @map(\"project_id\")\n  machineId String   @map(\"machine_id\")\n  /// absolute path on that machine\n  cwd       String\n  position  Int      @default(0)\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  project   Project  @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  machine   Machine  @relation(fields: [machineId], references: [id], onDelete: Cascade)\n\n  @@unique([projectId, machineId])\n  @@index([machineId])\n  @@map(\"project_machines\")\n}\n\nmodel Tab {\n  id               String       @id\n  projectId        String       @map(\"project_id\")\n  /// The machine this tab's tmux session runs on (one of the project's linked machines).\n  machineId        String       @map(\"machine_id\")\n  name             String\n  kind             TabKind      @default(terminal)\n  tmuxSession      String?      @unique @map(\"tmux_session\")\n  simulatorUdid    String?      @map(\"simulator_udid\")\n  position         Int          @default(0)\n  /// Monitor: what the tool in this tab is doing, as reported by its hooks (or the tmux fallback).\n  /// null = unknown (never reported). stateText = the pending question/notification, never scrollback.\n  state            TabState?\n  stateText        String?      @map(\"state_text\")\n  stateTool        String?      @map(\"state_tool\")\n  stateAt          DateTime?    @map(\"state_at\")\n  /// When the tab was last looked at while needing you; null or earlier than stateAt = still needs you.\n  stateSeenAt      DateTime?    @map(\"state_seen_at\")\n  /// Set while `state` is working; cleared when the tab leaves it. null = not working or never reported.\n  activity         TabActivity?\n  /// Claude Code's spinner verb that came with `activity` (one ASCII word); set and cleared with it.\n  activityVerb     String?      @map(\"activity_verb\")\n  /// API token that opened this tab through /mcp (null: opened in the browser). Used by close_tab and the per-token open-tab limit.\n  createdByTokenId String?      @map(\"created_by_token_id\")\n  createdAt        DateTime     @default(now()) @map(\"created_at\")\n  project          Project      @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  machine          Machine      @relation(fields: [machineId], references: [id], onDelete: Cascade)\n  tasks            Task[]\n  events           TabEvent[]\n\n  @@index([projectId])\n  @@index([machineId])\n  @@index([createdByTokenId])\n  @@map(\"tabs\")\n}\n\nenum TabState {\n  working\n  waiting_input\n  waiting_permission\n  idle\n  error\n}\n\n/// What a working agent is doing, from the tool it is about to call (monitor/activity.ts).\nenum TabActivity {\n  coding\n  reading\n  researching\n  planning\n  terminal\n  working\n}\n\n/// One monitor event for a tab (hook from Claude Code / Codex, or the tmux fallback).\n/// `text` is the tool's own message (question, permission prompt), capped — never terminal content.\nmodel TabEvent {\n  id        String   @id\n  tabId     String   @map(\"tab_id\")\n  kind      TabState\n  tool      String\n  text      String?\n  meta      Json     @default(\"{}\")\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  tab       Tab      @relation(fields: [tabId], references: [id], onDelete: Cascade)\n\n  @@index([tabId, createdAt])\n  @@map(\"tab_events\")\n}\n\n/// Hook install on a machine: the token its hook script posts with (sha256 only). Row = installed.\nmodel MachineHook {\n  machineId   String   @id @map(\"machine_id\")\n  tokenHash   String   @unique @map(\"token_hash\")\n  installedAt DateTime @default(now()) @map(\"installed_at\")\n  machine     Machine  @relation(fields: [machineId], references: [id], onDelete: Cascade)\n\n  @@map(\"machine_hooks\")\n}\n\n/// Tickets sincronizados das integrações (staging). Só viram task quando o usuário manda pro backlog.\nmodel Ticket {\n  id            String              @id\n  projectId     String              @map(\"project_id\")\n  integrationId String              @map(\"integration_id\")\n  provider      IntegrationProvider\n  /// \"linear:<id>\" | \"jira:<KEY>\" | \"github:<owner/repo>#<n>\"\n  externalKey   String              @map(\"external_key\")\n  identifier    String\n  title         String\n  description   String?\n  url           String\n  /// estado bruto no provedor e o status mapeado\n  state         String\n  status        TaskStatus\n  meta          Json                @default(\"{}\")\n  /// task criada a partir deste ticket (null = ainda não importado)\n  taskId        String?             @unique @map(\"task_id\")\n  syncedAt      DateTime            @default(now()) @map(\"synced_at\")\n  createdAt     DateTime            @default(now()) @map(\"created_at\")\n  project       Project             @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@unique([projectId, externalKey])\n  @@index([projectId, integrationId])\n  @@map(\"tickets\")\n}\n\nenum TaskStatus {\n  backlog\n  todo\n  doing\n  done\n}\n\nmodel Task {\n  id          String     @id\n  projectId   String     @map(\"project_id\")\n  title       String\n  description String?\n  status      TaskStatus @default(todo)\n  position    Int        @default(0)\n  /// Reservado para integrações (GitHub/Jira/Linear): { provider, id, url, ... }\n  externalRef Json?      @map(\"external_ref\")\n  createdAt   DateTime   @default(now()) @map(\"created_at\")\n  updatedAt   DateTime   @default(now()) @updatedAt @map(\"updated_at\")\n  project     Project    @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  /// chave estável do ticket externo (\"linear:<id>\", \"jira:<key>\") para upsert no sync\n  externalKey String? @map(\"external_key\")\n  /// tab de terminal onde a task está sendo executada (run ou aberta manualmente)\n  tabId       String? @map(\"tab_id\")\n  tab         Tab?    @relation(fields: [tabId], references: [id], onDelete: SetNull)\n\n  /// Subtask: the parent task (one level only, enforced in TasksRepository). Subtasks have no\n  /// board column — `position` orders them among siblings — and are always local (no externalKey).\n  parentId String? @map(\"parent_id\")\n  parent   Task?   @relation(\"TaskSubtasks\", fields: [parentId], references: [id], onDelete: Cascade)\n  subtasks Task[]  @relation(\"TaskSubtasks\")\n\n  @@unique([projectId, externalKey])\n  @@index([projectId, status, position])\n  @@index([parentId, position])\n  @@map(\"tasks\")\n}\n\nmodel Note {\n  id        String   @id\n  projectId String   @unique @map(\"project_id\")\n  content   String   @default(\"\")\n  updatedAt DateTime @default(now()) @updatedAt @map(\"updated_at\")\n  project   Project  @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@map(\"notes\")\n}\n\nenum IntegrationProvider {\n  github\n  linear\n  jira\n}\n\n/// Credenciais de serviços externos (nível conta).